<?php defined('ABSPATH')||exit;$post=get_post();$cover=has_post_thumbnail();$reading=fuwari_reading($post);?>
<article class="card-base flex flex-col-reverse md:flex-col w-full rounded-[var(--radius-large)] overflow-hidden relative onload-animation fuwari-post-card <?php if($cover)echo 'has-cover';?>">
<div class="pl-6 md:pl-9 pr-6 md:pr-2 pt-6 md:pt-7 pb-6 relative fuwari-card-text"><a href="<?php the_permalink();?>" class="transition group w-full block font-bold mb-3 text-3xl text-90 hover:text-[var(--primary)] active:text-[var(--title-active)] before:w-1 before:h-5 before:rounded-md before:bg-[var(--primary)] before:absolute before:top-[35px] before:left-[18px] before:hidden md:before:block"><?php the_title();?><?php echo fuwari_icon('material-symbols:chevron-right-rounded','inline text-[2rem] text-[var(--primary)] md:hidden translate-y-0.5 absolute');?></a>
<?php fuwari_metadata($post,'mb-4',true,true);?><div class="transition text-75 mb-3.5 pr-4"><?php echo esc_html(fuwari_description($post));?></div><div class="text-sm text-black/30 dark:text-white/30 flex gap-4 transition"><div><?php echo $reading['words'].' '.fuwari_label($reading['words']===1?'word':'words');?></div><div>|</div><div><?php echo $reading['minutes'].' '.fuwari_label($reading['minutes']===1?'minute':'minutes');?></div></div></div>
<?php if($cover):?><a href="<?php the_permalink();?>" aria-label="<?php echo esc_attr(get_the_title());?>" class="group fuwari-card-cover relative rounded-xl overflow-hidden active:scale-95"><div class="absolute pointer-events-none z-10 w-full h-full group-hover:bg-black/30 transition"></div><?php the_post_thumbnail('large',['class'=>'w-full h-full object-cover','loading'=>'lazy']);?></a><?php else:?><a href="<?php the_permalink();?>" aria-label="<?php echo esc_attr(get_the_title());?>" class="!hidden md:!flex btn-regular w-[3.25rem] absolute right-3 top-3 bottom-3 rounded-xl bg-[var(--enter-btn-bg)] hover:bg-[var(--enter-btn-bg-hover)] active:bg-[var(--enter-btn-bg-active)] active:scale-95"><?php echo fuwari_icon('material-symbols:chevron-right-rounded','transition text-[var(--primary)] text-4xl mx-auto');?></a><?php endif;?></article><div class="transition border-t-[1px] border-dashed mx-6 border-black/10 dark:border-white/[0.15] last:border-t-0 md:hidden"></div>
